 @TempDir Path root;
 String output(){return "{\"type\":\"result\",\"subtype\":\"success\",\"is_error\":false,\"usage\":{\"input_tokens\":3,\"cache_creation_input_tokens\":2,\"cache_read_input_tokens\":1,\"output_tokens\":4},\"structured_output\":{\"summary\":\"ok\",\"findings\":[],\"warnings\":[]}}";}
 ExternalAgentRequest request() throws Exception {var file=Files.writeString(root.resolve("note.md"),"review this");return new ExternalAgentRequest(ExternalAgentRequest.Agent.CLAUDE,ExternalAgentRequest.Action.REVIEW,"review",root,file,"decisions","run","id");}
 @Test void isolatedClaudeReviewPassesBoundedSourceViaStdinAndAccountsUsage() throws Exception {
  var paid=new AtomicInteger();var runner=new ExternalAgentProcessRunner(){public Output run(List<String> command,Path cwd,String input,Duration total,Duration idle,int max,java.util.function.BooleanSupplier cancelled){assertNotEquals(root,cwd);if(command.contains("--version"))return new Output(ExternalAgentResult.Status.SUCCESS,"2.1.286 (Claude Code)","",0,1,false);if(command.contains("--help"))return new Output(ExternalAgentResult.Status.SUCCESS,"--safe-mode --print --tools --disallowedTools --strict-mcp-config --mcp-config --setting-sources --no-session-persistence --output-format --json-schema --max-turns --system-prompt --permission-mode --no-chrome","",0,1,false);if(command.contains("auth"))return new Output(ExternalAgentResult.Status.SUCCESS,"{\"authMethod\":\"claude.ai\"}","",0,1,false);assertTrue(command.contains("--safe-mode"));assertEquals("",command.get(command.indexOf("--tools")+1));assertEquals("mcp__*",command.get(command.indexOf("--disallowedTools")+1));assertEquals("3",command.get(command.indexOf("--max-turns")+1));assertTrue(input.contains("review this"));assertFalse(command.toString().contains("review this"));paid.incrementAndGet();return new Output(ExternalAgentResult.Status.SUCCESS,output(),"",0,1,false);}};
  var props=new ClaudeCodeProperties();props.setEnabled(true);var budget=new OutputLimitRunBudget(0,10,null,100);var run=new RunExecutionContext("run",budget,null,null,null);var executor=new ClaudeCodeExternalAgentExecutor(props,runner);assertTrue(executor.execute(request(),()->false,run.modelCallBudget()).success());assertEquals(1,paid.get());assertEquals(10,budget.totalTokens());assertEquals(9,budget.remainingLlmCalls());
 }
 @Test void parserAuthorizationAndDefaultsKeepProvidersSeparate(){assertEquals("claude",ExternalAgentCommandRequest.parse("/agent claude review docs/a.md").agent());assertTrue(ExternalAgentAuthorization.explicitRequest("Claude Code にレビューして",ExternalAgentRequest.Agent.CLAUDE));assertFalse(ExternalAgentAuthorization.explicitRequest("Claude Code にレビューして"));assertFalse(ExternalAgentAuthorization.explicitRequest("Codex にレビューして",ExternalAgentRequest.Agent.CLAUDE));assertFalse(new ClaudeCodeProperties().isEnabled());}
 ClaudeCodeExternalAgentExecutor executor(AtomicInteger paid,String text,String auth,Runnable effect){var props=new ClaudeCodeProperties();props.setEnabled(true);return new ClaudeCodeExternalAgentExecutor(props,new ExternalAgentProcessRunner(){public Output run(List<String> command,Path cwd,String input,Duration total,Duration idle,int max,java.util.function.BooleanSupplier cancelled){if(command.contains("--version"))return new Output(ExternalAgentResult.Status.SUCCESS,"2.1.286 (Claude Code)","",0,1,false);if(command.contains("--help"))return new Output(ExternalAgentResult.Status.SUCCESS,"--safe-mode --print --tools --disallowedTools --strict-mcp-config --mcp-config --setting-sources --no-session-persistence --output-format --json-schema --max-turns --system-prompt --permission-mode --no-chrome","",0,1,false);if(command.contains("auth"))return new Output(ExternalAgentResult.Status.SUCCESS,auth,"",0,1,false);paid.incrementAndGet();effect.run();return new Output(ExternalAgentResult.Status.SUCCESS,text,"",0,1,false);}});}
 @Test void subscriptionRunnerRetainsOauthButRemovesEveryApiAndCloudOverride(){var environment=new HashMap<>(Map.of("ANTHROPIC_API_KEY","fake-key","anthropic_auth_token","fake-token","CLAUDE_CODE_USE_BEDROCK","1","ANTHROPIC_PROFILE","paid-api","CLAUDE_CODE_OAUTH_TOKEN","fake-subscription","CLAUDE_CONFIG_DIR","account-directory","CLAUDE_CODE_SIMPLE","1"));new ClaudeCodeProcessRunner().configureEnvironment(environment);assertFalse(environment.containsKey("ANTHROPIC_API_KEY"));assertFalse(environment.containsKey("anthropic_auth_token"));assertFalse(environment.containsKey("CLAUDE_CODE_USE_BEDROCK"));assertFalse(environment.containsKey("ANTHROPIC_PROFILE"));assertFalse(environment.containsKey("CLAUDE_CODE_SIMPLE"));assertEquals("fake-subscription",environment.get("CLAUDE_CODE_OAUTH_TOKEN"));assertEquals("account-directory",environment.get("CLAUDE_CONFIG_DIR"));assertEquals("1",environment.get("CLAUDE_CODE_SAFE_MODE"));}
 @Test void apiOrUnknownAuthenticationCannotStartReviewOrSpendBudget() throws Exception {for(String auth:List.of("{\"authMethod\":\"api_key\"}","{\"authMethod\":\"third_party\"}","{\"authMethod\":\"none\"}","{\"authMethod\":\"claude.ai\",\"authMethod\":\"api_key\"}","not json")){var paid=new AtomicInteger();var budget=new OutputLimitRunBudget(0,10,null,100);var run=new RunExecutionContext("run",budget,null,null,null);assertEquals(ExternalAgentResult.Status.REJECTED,executor(paid,output(),auth,()->{}).execute(request(),()->false,run.modelCallBudget()).status());assertEquals(0,paid.get());assertEquals(10,budget.remainingLlmCalls());}}
 @Test void malformedOrUnreportedUsageFailsClosedAndCallLimitPreventsPaidExecution() throws Exception {for(String text:List.of(output().replace("\"input_tokens\":3","\"input_tokens\":-1"),output().replace("\"output_tokens\":4","\"output_tokens\":4.5"),output().replace("\"input_tokens\":3","\"input_tokens\":3,\"input_tokens\":4"),output().replace("\"input_tokens\":3","\"input_tokens\":2147483647"),output().replace("\"is_error\":false","\"is_error\":true"),output()+"{}")){var paid=new AtomicInteger();var budget=new OutputLimitRunBudget(0,10,null,100);var run=new RunExecutionContext("run",budget,null,null,null);assertTrue(assertThrows(dev.mikoto2000.rei.core.stagnation.ExecutionStoppedException.class,()->executor(paid,text,"{\"authMethod\":\"claude.ai\"}",()->{}).execute(request(),()->false,run.modelCallBudget())).getMessage().contains("TOKEN_USAGE_UNKNOWN"));assertTrue(budget.usageUnknown());assertEquals(1,paid.get());}var paid=new AtomicInteger();var run=new RunExecutionContext("run",new OutputLimitRunBudget(0,0),null,null,null);assertThrows(dev.mikoto2000.rei.core.stagnation.ExecutionStoppedException.class,()->executor(paid,output(),"{\"authMethod\":\"oauth_token\"}",()->{}).execute(request(),()->false,run.modelCallBudget()));assertEquals(0,paid.get());}
 @Test void secretOversizedBinaryAndOutsideInputsNeverReachClaude() throws Exception {var paid=new AtomicInteger();var executor=executor(paid,output(),"{\"authMethod\":\"claude.ai\"}",()->{});for(var item:List.of(Map.entry(".env","PRIVATE"),Map.entry("large.md","x".repeat(65537)),Map.entry("binary.txt","a\0b"))){var file=Files.writeString(root.resolve(item.getKey()),item.getValue());var request=new ExternalAgentRequest(ExternalAgentRequest.Agent.CLAUDE,ExternalAgentRequest.Action.REVIEW,"review",root,file,"","run","id");assertEquals(ExternalAgentResult.Status.UNAVAILABLE,executor.execute(request,()->false).status());}var project=Files.createDirectory(root.resolve("project"));var outside=Files.writeString(root.resolve("outside.txt"),"outside");var request=new ExternalAgentRequest(ExternalAgentRequest.Agent.CLAUDE,ExternalAgentRequest.Action.REVIEW,"review",project,outside,"","run","id");assertEquals(ExternalAgentResult.Status.UNAVAILABLE,executor.execute(request,()->false).status());assertEquals(0,paid.get());}
 @Test void directorySnapshotHasHardFileCountBoundAndRedactsCredentialValues() throws Exception {var project=Files.createDirectory(root.resolve("project"));Files.writeString(project.resolve("note.md"),"Authorization: Bearer sk-abcdefghijklmnopqrstuvwxyz123456789");Files.writeString(project.resolve(".env"),"must not send");var snapshot=ClaudeCodeExternalAgentExecutor.snapshot(project,null,()->false,System.nanoTime()+Duration.ofSeconds(2).toNanos());assertEquals(1,snapshot.size());assertFalse(snapshot.toString().contains("must not send"));assertFalse(snapshot.toString().contains("sk-abcdefghijklmnopqrstuvwxyz123456789"));for(int i=0;i<32;i++)Files.writeString(project.resolve("file-"+i+".txt"),"safe");assertThrows(java.io.IOException.class,()->ClaudeCodeExternalAgentExecutor.snapshot(project,null,()->false,System.nanoTime()+Duration.ofSeconds(2).toNanos()));}
 @Test void invalidStructuredReviewAndChangedSourceCannotClaimSuccessfulReview() throws Exception {var paid=new AtomicInteger();assertEquals(ExternalAgentResult.Status.FAILED,executor(paid,output().replace("\"summary\":\"ok\"","\"summary\":42"),"{\"authMethod\":\"claude.ai\"}",()->{}).execute(request(),()->false).status());var request=request();var budget=new OutputLimitRunBudget(0,10,null,100);var run=new RunExecutionContext("run",budget,null,null,null);assertEquals(ExternalAgentResult.Status.FAILED,executor(paid,output(),"{\"authMethod\":\"claude.ai\"}",()->{try{Files.writeString(request.target(),"changed");}catch(Exception error){throw new RuntimeException(error);}}).execute(request,()->false,run.modelCallBudget()).status());assertEquals(10,budget.totalTokens());}
 @Test void cancelledPreparationNeverStartsReviewAndNativeShimsAreRejected() throws Exception {var paid=new AtomicInteger();assertThrows(java.util.concurrent.CancellationException.class,()->executor(paid,output(),"{\"authMethod\":\"claude.ai\"}",()->{}).execute(request(),()->true));assertEquals(0,paid.get());if(System.getProperty("os.name").startsWith("Windows")){var props=new ClaudeCodeProperties();props.setCommand("claude.cmd");assertThrows(IllegalArgumentException.class,()->new ClaudeCodeExternalAgentExecutor(props,new ExternalAgentProcessRunner()).executable());}}
 @Test void legacyHistoryMigrationPreservesCodexAndReadToolsFilterProviders() throws Exception {var source=new org.springframework.jdbc.datasource.DriverManagerDataSource("jdbc:sqlite:"+root.resolve("legacy.db"));var jdbc=new org.springframework.jdbc.core.JdbcTemplate(source);jdbc.execute("CREATE TABLE external_reviews(id TEXT PRIMARY KEY,project TEXT NOT NULL,root TEXT NOT NULL,session TEXT NOT NULL,run TEXT NOT NULL,target TEXT,previous TEXT,status TEXT NOT NULL,created INTEGER NOT NULL,completed INTEGER,result TEXT)");jdbc.update("INSERT INTO external_reviews VALUES('old','p',?,'chat','run',NULL,NULL,'STARTED',1,NULL,NULL)",root.toString());var history=new ExternalReviewRepository(source,Clock.systemUTC());assertEquals("codex",history.get("p","old").agent());var owner=new AgentRunContext("run","chat",root,"p");history.start(owner,"claude",root,null,null,"claude");var restarted=new ExternalReviewRepository(source,Clock.systemUTC());assertEquals("claude",restarted.get("p","claude").agent());try(var service=new ExternalAgentDelegationService((request,cancelled)->{throw new AssertionError();},new dev.mikoto2000.rei.core.service.CommandCancellationService(),new dev.mikoto2000.rei.event.AgentEventFactory(Clock.systemUTC()),event->{},Optional.empty())){var tools=new ExternalAgentTools(service);tools.reviewHistory(restarted);var run=new RunExecutionContext("run",new OutputLimitRunBudget(0,10),null,null,null);run.setRunContext(owner);var context=new org.springframework.ai.chat.model.ToolContext(Map.of(RunExecutionContext.KEY,run));assertEquals(List.of("old"),tools.listCodexReviews(context).stream().map(ExternalReviewRepository.Review::id).toList());assertEquals(List.of("claude"),tools.listClaudeCodeReviews(context).stream().map(ExternalReviewRepository.Review::id).toList());assertThrows(IllegalArgumentException.class,()->tools.getCodexReview("claude",context));assertThrows(IllegalArgumentException.class,()->tools.getClaudeCodeReview("old",context));}}
 @Test void routerAndSemanticToolKeepAuthorizedProviderAndBudget() {var codex=org.mockito.Mockito.mock(ExternalAgentExecutor.class);var claude=org.mockito.Mockito.mock(ExternalAgentExecutor.class);var router=new RoutingExternalAgentExecutor(codex,claude);var budget=org.mockito.Mockito.mock(dev.mikoto2000.rei.llm.ModelCallBudget.class);var request=new ExternalAgentRequest(ExternalAgentRequest.Agent.CLAUDE,ExternalAgentRequest.Action.REVIEW,"review",root,null,"","run","id");java.util.function.BooleanSupplier cancelled=()->false;router.execute(request,cancelled,budget);org.mockito.Mockito.verify(claude).execute(request,cancelled,budget);org.mockito.Mockito.verifyNoInteractions(codex);var service=org.mockito.Mockito.mock(ExternalAgentDelegationService.class);var tools=new ExternalAgentTools(service);tools.requestClaudeCodeReview("review",null,null,new org.springframework.ai.chat.model.ToolContext(Map.of()));org.mockito.Mockito.verify(service).review(null,ExternalAgentRequest.Agent.CLAUDE,"review",null,null);var callback=Arrays.stream(org.springframework.ai.tool.method.MethodToolCallbackProvider.builder().toolObjects(tools).build().getToolCallbacks()).filter(tool->tool.getToolDefinition().name().equals("requestClaudeCodeReview")).findFirst().orElseThrow();assertFalse(callback.getToolDefinition().inputSchema().contains("projectRoot"));assertTrue(callback.getToolDefinition().description().contains("explicitly"));}
 @Test void obsoleteClaudeVersionCannotStartReviewEvenIfHelpAdvertisesFlags() throws Exception {var paid=new AtomicInteger();var props=new ClaudeCodeProperties();props.setEnabled(true);var executor=new ClaudeCodeExternalAgentExecutor(props,new ExternalAgentProcessRunner(){public Output run(List<String> command,Path cwd,String input,Duration total,Duration idle,int max,java.util.function.BooleanSupplier cancelled){if(command.contains("--version"))return new Output(ExternalAgentResult.Status.SUCCESS,"2.1.168 (Claude Code)","",0,1,false);if(command.contains("--help"))return new Output(ExternalAgentResult.Status.SUCCESS,"--safe-mode --print --tools --disallowedTools --strict-mcp-config --mcp-config --setting-sources --no-session-persistence --output-format --json-schema --max-turns --system-prompt --permission-mode --no-chrome","",0,1,false);if(command.contains("auth"))return new Output(ExternalAgentResult.Status.SUCCESS,"{\"authMethod\":\"claude.ai\"}","",0,1,false);paid.incrementAndGet();return new Output(ExternalAgentResult.Status.SUCCESS,output(),"",0,1,false);}});assertEquals(ExternalAgentResult.Status.UNAVAILABLE,executor.execute(request(),()->false).status());assertEquals(0,paid.get());}
 @Test void usageReservationSurvivesGoalRepositoryRestart() throws Exception {var source=new org.springframework.jdbc.datasource.DriverManagerDataSource("jdbc:sqlite:"+root.resolve("goal.db"));var props=new dev.mikoto2000.rei.llm.LlmProperties();props.getOutputLimit().setMaxTotalTokensPerGoal(100);var goals=new dev.mikoto2000.rei.goal.GoalRepository(source,Clock.systemUTC(),props);var goal=goals.create(new AgentRunContext("source","chat",root,"p"),"Artifact","out.txt","a".repeat(64),3,10);var claim=goals.claim("p",goal.id());var id=goals.beginAttempt(claim);var budget=new OutputLimitRunBudget(0,10,goals.modelBudget(claim,id));var run=new RunExecutionContext(id,budget,null,null,null);var paid=new AtomicInteger();assertTrue(executor(paid,output(),"{\"authMethod\":\"claude.ai\"}",()->{}).execute(request(),()->false,run.modelCallBudget()).success());var restarted=new dev.mikoto2000.rei.goal.GoalRepository(source,Clock.systemUTC());assertEquals(10,restarted.get("p",goal.id()).totalTokens());assertEquals(1,restarted.get("p",goal.id()).llmCallsUsed());}
 @Test void disabledInvalidLimitsAndUnsupportedActionsNeverStartCli() throws Exception {var runner=new ExternalAgentProcessRunner(){public Output run(List<String> command,Path cwd,String input,Duration total,Duration idle,int max,java.util.function.BooleanSupplier cancelled){throw new AssertionError();}};var props=new ClaudeCodeProperties();var executor=new ClaudeCodeExternalAgentExecutor(props,runner);assertEquals(ExternalAgentResult.Status.REJECTED,executor.execute(request(),()->false).status());props.setEnabled(true);props.setMaxOutputBytes(4194305);assertEquals(ExternalAgentResult.Status.REJECTED,executor.execute(request(),()->false).status());props.setMaxOutputBytes(1000);var request=request();assertEquals(ExternalAgentResult.Status.REJECTED,executor.execute(new ExternalAgentRequest(ExternalAgentRequest.Agent.CLAUDE,ExternalAgentRequest.Action.PROPOSE_FIX,"fix",root,request.target(),"","run","id"),()->false).status());}
 @Test void slashAdvisorSelectsClaudeAndKeepsResultOutOfUserText(){var service=org.mockito.Mockito.mock(ExternalAgentDelegationService.class);var run=new RunExecutionContext("run",new OutputLimitRunBudget(0,10),null,null,null);run.setRunContext(new AgentRunContext("run","chat",root,"p"));run.setUserRequest("/agent claude review note.md");org.mockito.Mockito.when(service.review(org.mockito.ArgumentMatchers.eq(run),org.mockito.ArgumentMatchers.eq(ExternalAgentRequest.Agent.CLAUDE),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.eq("note.md"),org.mockito.ArgumentMatchers.anyString())).thenReturn(new ExternalAgentResult(ExternalAgentResult.Status.SUCCESS,"Claude finding",List.of(),List.of(),1,0,"PRIVATE LOG"));var options=org.springframework.ai.openai.OpenAiChatOptions.builder().toolContext(Map.of(RunExecutionContext.KEY,run)).build();var request=org.springframework.ai.chat.client.ChatClientRequest.builder().prompt(new org.springframework.ai.chat.prompt.Prompt(new org.springframework.ai.chat.messages.UserMessage(run.userRequest()),options)).build();var advisor=new ExternalAgentReviewAdvisor(service);var response=advisor.before(request,null);assertEquals(run.userRequest(),response.prompt().getUserMessage().getText());assertTrue(response.prompt().getSystemMessage().getText().contains("Claude finding"));assertFalse(response.prompt().getSystemMessage().getText().contains("PRIVATE LOG"));advisor.before(request,null);org.mockito.Mockito.verify(service,org.mockito.Mockito.times(1)).review(org.mockito.ArgumentMatchers.eq(run),org.mockito.ArgumentMatchers.eq(ExternalAgentRequest.Agent.CLAUDE),org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.eq("note.md"),org.mockito.ArgumentMatchers.anyString());}
 @Test void configAndHistoryReadPolicyBindWithoutMakingReviewReadOnlyCapability(){var source=new org.springframework.boot.context.properties.source.MapConfigurationPropertySource(Map.of("rei.external-agents.claude.enabled","true","rei.external-agents.claude.command","native-claude","rei.external-agents.claude.total-timeout","30s"));var props=new org.springframework.boot.context.properties.bind.Binder(source).bind("rei.external-agents.claude",org.springframework.boot.context.properties.bind.Bindable.of(ClaudeCodeProperties.class)).get();assertTrue(props.isEnabled());assertEquals("native-claude",props.getCommand());assertEquals(Duration.ofSeconds(30),props.getTotalTimeout());var policy=new dev.mikoto2000.rei.core.policy.ToolPermissionPolicy(new dev.mikoto2000.rei.core.policy.ToolPermissionProperties(false,Set.of(),Set.of(),Map.of()));assertEquals(Set.of(dev.mikoto2000.rei.core.policy.ActionCapability.READ),policy.capabilities("listClaudeCodeReviews"));assertTrue(policy.capabilities("requestClaudeCodeReview").contains(dev.mikoto2000.rei.core.policy.ActionCapability.EXTERNAL_SIDE_EFFECT));}
 @Test void cancelledAndUnexpectedFailureHistoryUseClaudeNameWithoutPrivateExceptionText(){var history=new ExternalReviewRepository(new org.springframework.jdbc.datasource.DriverManagerDataSource("jdbc:sqlite:"+root.resolve("errors.db")),Clock.systemUTC());for(boolean cancel:List.of(true,false)){try(var service=new ExternalAgentDelegationService((request,cancelled)->{if(cancel)return new ExternalAgentResult(ExternalAgentResult.Status.CANCELLED,"cancelled",List.of(),List.of(),1,null,"");throw new IllegalStateException("PRIVATE ERROR");},new dev.mikoto2000.rei.core.service.CommandCancellationService(),new dev.mikoto2000.rei.event.AgentEventFactory(Clock.systemUTC()),event->{},Optional.empty())){service.reviewHistory(history);String id="error-"+cancel;var run=new RunExecutionContext(id,new OutputLimitRunBudget(0,10),null,null,null);run.setRunContext(new AgentRunContext(id,"chat",root,"p"));run.setUserRequest("Claude Code にレビューして");if(cancel){assertThrows(java.util.concurrent.CancellationException.class,()->service.review(run,ExternalAgentRequest.Agent.CLAUDE,"review",null,null));assertTrue(run.isCancelled());}else assertEquals(ExternalAgentResult.Status.FAILED,service.review(run,ExternalAgentRequest.Agent.CLAUDE,"review",null,null).status());var saved=history.list("p","claude").stream().filter(review->review.runId().equals(id)).findFirst().orElseThrow();assertTrue(saved.result().summary().startsWith("Claude Code"));assertFalse(saved.result().summary().contains("PRIVATE ERROR"));}}}
 @Test void sharedServiceSavesProviderAndCannotReuseClaudeHistoryAsCodexSession() throws Exception {
  var history=new ExternalReviewRepository(new org.springframework.jdbc.datasource.DriverManagerDataSource("jdbc:sqlite:"+root.resolve("history.db")),Clock.systemUTC());var observed=new java.util.concurrent.CopyOnWriteArrayList<dev.mikoto2000.rei.event.AgentEvent>();var calls=new AtomicInteger();
  var executor=new ExternalAgentExecutor(){public ExternalAgentResult execute(ExternalAgentRequest request,java.util.function.BooleanSupplier cancelled){throw new AssertionError();}public ExternalAgentResult execute(ExternalAgentRequest request,java.util.function.BooleanSupplier cancelled,dev.mikoto2000.rei.llm.ModelCallBudget budget){assertEquals(ExternalAgentRequest.Agent.CLAUDE,request.agent());budget.run();budget.recordTotalTokens(5);calls.incrementAndGet();return new ExternalAgentResult(ExternalAgentResult.Status.SUCCESS,"ok",List.of(),List.of(),1,0,"");}};
  try(var service=new ExternalAgentDelegationService(executor,new dev.mikoto2000.rei.core.service.CommandCancellationService(),new dev.mikoto2000.rei.event.AgentEventFactory(Clock.systemUTC()),observed::add,Optional.empty())){service.reviewHistory(history);var budget=new OutputLimitRunBudget(0,10,null,100);var run=new RunExecutionContext("run",budget,null,null,null);run.setRunContext(new AgentRunContext("run","chat",root,"p"));run.setUserRequest("Claude Code にレビューして");var result=service.review(run,ExternalAgentRequest.Agent.CLAUDE,"review",null,null);assertTrue(result.success());assertEquals("claude",history.get("p",result.reviewId()).agent());assertEquals(5,budget.totalTokens());run.setUserRequest("Codex にレビューして");assertEquals(ExternalAgentResult.Status.REJECTED,service.review(run,"again",null,null).status());var other=new RunExecutionContext("other",new OutputLimitRunBudget(0,10),null,null,null);other.setRunContext(new AgentRunContext("other","chat",root,"p"));other.setUserRequest("Codex にレビューして");assertEquals(ExternalAgentResult.Status.REJECTED,service.rereview(other,result.reviewId(),"review",null).status());assertEquals(1,calls.get());assertTrue(observed.toString().contains("claude"));}
 }
